class Solution {
    public int maxProfit(int[] prices) {
        int res = 0;                // 记录最大利润
        int minprice = prices[0];   // 记录遍历到当前位置的【历史最低价格】
        // 从第2天开始遍历
        for(int i = 1; i < prices.length; i++){
            // 1. 计算今天卖出的利润，更新最大利润
            res = Math.max(res, prices[i] - minprice);
            // 2. 更新历史最低价
            minprice = Math.min(minprice, prices[i]);
        }
        return res;  // 返回最大利润
    }
}
